import{_ as t,a,o as r,a4 as s}from"./chunks/framework.-FZumj2l.js";const l=JSON.parse('{"title":"Search & SEO","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/search-seo/index.md","filePath":"api/rest-api/admin/marketing/search-seo/index.md","lastUpdated":1784902076000}'),o={name:"api/rest-api/admin/marketing/search-seo/index.md"};function n(i,e,h,d,c,m){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="search-seo" tabindex="-1">Search &amp; SEO <a class="header-anchor" href="#search-seo" aria-label="Permalink to &quot;Search &amp; SEO&quot;">​</a></h1><p>Search &amp; SEO controls <strong>how the store is searched and how search engines index it</strong>. It mirrors the admin <strong>Marketing → Search &amp; SEO</strong> menu.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/search-seo/url-rewrites/">URL Rewrites</a></td><td>301 / 302 redirects from an old or custom path to a target — keeps links alive when slugs change.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-terms/">Search Terms</a></td><td>What shoppers typed into storefront search, auto-recorded with result counts and use counts.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms/">Search Synonyms</a></td><td>Word groups that widen search matches (a query for one term also matches the others).</td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/sitemaps/">Sitemaps</a></td><td>XML sitemap definitions and the generated files crawlers consume.</td></tr></tbody></table><h2 id="how-they-fit-together" tabindex="-1">How they fit together <a class="header-anchor" href="#how-they-fit-together" aria-label="Permalink to &quot;How they fit together&quot;">​</a></h2><p>The four resources cover the two halves of discoverability. <strong>Search Terms</strong> and <strong>Search Synonyms</strong> shape <em>on-site</em> search: search terms reveal what shoppers actually look for (and where results are thin), and synonyms widen recall so those queries return more products. <strong>URL Rewrites</strong> and <strong>Sitemaps</strong> shape <em>off-site</em> discovery: rewrites preserve inbound links across slug changes, and sitemaps hand the crawler the full list of product, category, and page URLs to index.</p><p>All Search &amp; SEO endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',7)]))}const u=t(o,[["render",n]]);export{l as __pageData,u as default};
